architecture.h4_f:
msg = CBOR{v:1, text, reply_to, sent_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, text, odpovědět_na?, id_vlákna?, zmínky?, odesláno}
ct = AES-GCM-256-Encrypt(room_key, nonce, pt, aad=hex(room_id))
drát = CBOR{
  v: 1,
  ciphertext: hex(ct), // proměnná délka
  nonce: hex(12 B),
  sender_pseudo: hex(16 B),
  send_at: unix_ms
}

cryptoWire.h5_f:
vnější = CBOR{
  zdrojový_uzel: hex32,
  target_user: int64,
  inner_ciphertext: bytes,
  inner_nonce: bytes,
  send_at: unix_ms
}
sig = Ed25519-Sign(source_priv, vnější)
POST /federation/deliver { obálka: vnější, sig: hex64 }

auth.h1_f:
POST /api/authentication/register
  { uživatelské jméno, heslo, x25519_public_key, display_name, phone?, email?, avatar_emoji }

Odpověď 201 Vytvořeno:
  { access_token, refresh_token, user_id, username, ... }

auth.h3_f:
užitečné zatížení přístupového_tokenu:
  { sub: user_id, jti: device_id, typ: "access", exp: now + 15min }
refresh_token užitečné zatížení:
  { sub: user_id, jti: device_id, typ: "refresh", exp: now + 30d }

HS256-podepsané 64bajtovým tajemstvím uzlu z .env

auth.h4_f:
register_begin(): výzva = rand(32)
                    options = { rp.id, user.id, pubKeyCredParams, challenge }
                    možnosti vrácení

registrace_dokončit(atest):
  ověřit atestaci proti TPM / Secure Enclave root CA
  store { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128bitový hex, ttl: 60 }
QR payload = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → nové zařízení zaregistrováno; JWT se vrátili.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(pokojová_pseudo_sůl, id_sendera)[:16] // 32 hex
ciphertext = AES-GCM-Encrypt(room_key, nonce, CBOR_payload, aad=room_id)

Vějířový rámec: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {název souboru, velikost, chunk_size_hint}
            ← {upload_id, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
finalize POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL na nedokončené: 24 hodin

files.h4_f:
deny_list = {
  "aplikace/x-dosexec",
  "application/x-sharedlib",
  "aplikace/x-mach-binary",
}
if magic.from_buffer(buf[:1024]) v deny_list: return 415

presence.h1_f:
klient: při prvním stisku klávesy → odeslat {type:"t", state:"start"}
         žádné další odesílání po dobu 3 s, pokud se stav nezmění
         10 s po posledním stisku klávesy → odeslat {type:"t", stav:"stop"}
přijímač: automatické zastavení 10 s po posledním "startu", pokud nedojde k "stop".

presence.h2_f:
POST /api/rooms/{id}/přečíst { last_read_message_id }

if user.hides_receipts:
   netrvat; nevysílat
   nepodávejte tomuto uživateli účtenky jiných uživatelů
jinak:
   UPSERT read_receipts VALUES (room_id, user_id, message_id, NOW())
   vysílání {type:"r", room, user, message_id}

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS vysílání {type:"c", kind:"invite", call_id}
WS vysílání {type:"c", kind:"offer", sdp}
WS vysílání {type:"c", kind:"answer", sdp}
WS vysílání {type:"c", kind:"candidate",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
obálka = {
  zdrojový_uzel: hex32,
  target_user : int64,
  inner_ciphertext: bytes,
  inner_nonce : bytes,
  send_at: unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(obálka))
POST /federace/doručení { obálka, podpis }

gossip.h3_f:
reklama = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(reklama))
užitečný obsah drby: [..., {ad, sig}, ...]

přijímač: ověřit sig proti ad.pubkey → uložit, pokud je to v pořádku
další: PoW 2^18 úvodních nul na {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template s {
  náhoda = naše náhoda,
  server_name = název našeho hostitele (nebo zabalené ECH),
  session_id = naše ID relace,
}
JA4 = t13d_xxxx_xxxx_xxxx (odpovídá aktuální stabilní verzi Chrome)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {název: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: doména(t) = základ32( SHA256(prvek ∥ YYYY-MM-DD) )[:16] + ".příklad"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Web SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
tool = sign_tool
input = zdrojový strom, klíče/release.key
manifest = {
  verze: "0.1.0",
  built_at: unix_ms,
  soubory: [{cesta, sha256, velikost}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
output = INTEGRITY.sig.json = {manifest, sign_by: pub_hex, sig: sig_hex}

bots.h1_f:
vytvořit: POST /api/bots {uživatelské jméno, zobrazované_jméno, kód}
          → {bot_id, token, pubkey}
běh: probíhá (korutina uvnitř uzlu)
      OR externí (dlouhý průzkum /api/bots/{id}/updates, token-auth'd)
zpráva: {text, podpis: Ed25519-Sign(bot_priv, canonical_msg)}

